import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.ePeAWSvT.js";const u=JSON.parse(`{"title":"Search & Filtering","description":"Find and filter captured HTTP traffic quickly with NectoProxy's search capabilities.","frontmatter":{"title":"Search & Filtering","description":"Find and filter captured HTTP traffic quickly with NectoProxy's search capabilities."},"headers":[],"relativePath":"features/search.md","filePath":"features/search.md","lastUpdated":1772297611000}`),r={name:"features/search.md"};function i(n,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="search-filtering" tabindex="-1">Search &amp; Filtering <a class="header-anchor" href="#search-filtering" aria-label="Permalink to &quot;Search &amp; Filtering&quot;">​</a></h1><p>NectoProxy provides multiple ways to find specific traffic entries. From the filter bar for quick column-based filtering to the global search for cross-session queries, these tools help you locate the requests you need in seconds, even across sessions with thousands of entries.</p><h2 id="filter-bar" tabindex="-1">Filter Bar <a class="header-anchor" href="#filter-bar" aria-label="Permalink to &quot;Filter Bar&quot;">​</a></h2><p>The filter bar sits at the top of the traffic list and provides <strong>column-based filtering</strong> to narrow down the displayed entries. Filters are applied in real time as you type.</p><h3 id="available-filters" tabindex="-1">Available Filters <a class="header-anchor" href="#available-filters" aria-label="Permalink to &quot;Available Filters&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Filter</th><th>Description</th><th>Examples</th></tr></thead><tbody><tr><td><strong>Method</strong></td><td>Filter by HTTP method</td><td><code>GET</code>, <code>POST</code>, <code>PUT</code>, <code>DELETE</code>, <code>PATCH</code></td></tr><tr><td><strong>Status</strong></td><td>Filter by response status code</td><td><code>200</code>, <code>404</code>, <code>500</code>, <code>2xx</code>, <code>4xx</code>, <code>5xx</code></td></tr><tr><td><strong>URL</strong></td><td>Filter by request URL (partial match)</td><td><code>/api/users</code>, <code>login</code>, <code>.js</code></td></tr><tr><td><strong>Host</strong></td><td>Filter by hostname</td><td><code>api.example.com</code>, <code>cdn.example.com</code></td></tr><tr><td><strong>Content Type</strong></td><td>Filter by response content type</td><td><code>application/json</code>, <code>text/html</code>, <code>image/</code></td></tr></tbody></table><h3 id="combining-filters" tabindex="-1">Combining Filters <a class="header-anchor" href="#combining-filters" aria-label="Permalink to &quot;Combining Filters&quot;">​</a></h3><p>Multiple filters can be applied simultaneously. When multiple filters are active, they work with <strong>AND logic</strong> -- an entry must match all active filters to be displayed.</p><details class="details custom-block"><summary>Example: Finding Failed API Calls</summary><p>To find all failed JSON API calls to your backend:</p><table tabindex="0"><thead><tr><th>Filter</th><th>Value</th></tr></thead><tbody><tr><td>Host</td><td><code>api.example.com</code></td></tr><tr><td>Status</td><td><code>5xx</code></td></tr><tr><td>Content Type</td><td><code>application/json</code></td></tr></tbody></table><p>This shows only requests to <code>api.example.com</code> that returned a 5xx error with a JSON response body.</p></details><h3 id="status-code-filtering" tabindex="-1">Status Code Filtering <a class="header-anchor" href="#status-code-filtering" aria-label="Permalink to &quot;Status Code Filtering&quot;">​</a></h3><p>Status codes can be filtered by exact code or by class:</p><table tabindex="0"><thead><tr><th>Input</th><th>Matches</th></tr></thead><tbody><tr><td><code>200</code></td><td>Only 200 OK responses</td></tr><tr><td><code>404</code></td><td>Only 404 Not Found responses</td></tr><tr><td><code>2xx</code></td><td>All successful responses (200-299)</td></tr><tr><td><code>3xx</code></td><td>All redirect responses (300-399)</td></tr><tr><td><code>4xx</code></td><td>All client error responses (400-499)</td></tr><tr><td><code>5xx</code></td><td>All server error responses (500-599)</td></tr></tbody></table><h3 id="url-filtering" tabindex="-1">URL Filtering <a class="header-anchor" href="#url-filtering" aria-label="Permalink to &quot;URL Filtering&quot;">​</a></h3><p>URL filtering performs a <strong>partial match</strong> against the full request URL (including query parameters). This means:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Filter: /api/users</span></span>
<span class="line"><span>Matches:</span></span>
<span class="line"><span>  https://example.com/api/users</span></span>
<span class="line"><span>  https://example.com/api/users/123</span></span>
<span class="line"><span>  https://example.com/api/users?page=2</span></span>
<span class="line"><span>  https://example.com/v2/api/users/search</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For more precise URL matching (glob, wildcard, regex), use the <a href="./rules-engine.html">Rules Engine</a> to highlight or flag specific requests instead of the filter bar.</p></div><h3 id="clearing-filters" tabindex="-1">Clearing Filters <a class="header-anchor" href="#clearing-filters" aria-label="Permalink to &quot;Clearing Filters&quot;">​</a></h3><p>Click the <strong>Clear</strong> button next to the filter bar to remove all active filters and show the complete traffic list.</p><h2 id="global-search" tabindex="-1">Global Search <a class="header-anchor" href="#global-search" aria-label="Permalink to &quot;Global Search&quot;">​</a></h2><p>Global search lets you search across <strong>all sessions</strong> for traffic entries matching your query. This is useful when you do not remember which session contains the request you are looking for.</p><h3 id="activating-global-search" tabindex="-1">Activating Global Search <a class="header-anchor" href="#activating-global-search" aria-label="Permalink to &quot;Activating Global Search&quot;">​</a></h3><p>Press <strong><code>Ctrl+Shift+F</code></strong> (or <strong><code>Cmd+Shift+F</code></strong> on macOS) to open the global search panel.</p><h3 id="search-scope" tabindex="-1">Search Scope <a class="header-anchor" href="#search-scope" aria-label="Permalink to &quot;Search Scope&quot;">​</a></h3><p>Global search queries against:</p><ul><li>Request URL</li><li>Request headers (names and values)</li><li>Response headers (names and values)</li><li>Request body content</li><li>Response body content</li><li>Annotations (notes and tags)</li></ul><h3 id="search-syntax" tabindex="-1">Search Syntax <a class="header-anchor" href="#search-syntax" aria-label="Permalink to &quot;Search Syntax&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Query</th><th>Searches For</th></tr></thead><tbody><tr><td><code>api/users</code></td><td>Any entry with &quot;api/users&quot; anywhere in URL, headers, or body</td></tr><tr><td><code>&quot;exact phrase&quot;</code></td><td>The exact phrase in quotes</td></tr><tr><td><code>Authorization: Bearer</code></td><td>Entries with a specific header pattern</td></tr><tr><td><code>error</code></td><td>Any entry containing the word &quot;error&quot;</td></tr></tbody></table><h3 id="search-results" tabindex="-1">Search Results <a class="header-anchor" href="#search-results" aria-label="Permalink to &quot;Search Results&quot;">​</a></h3><p>Results are displayed in a dropdown list showing:</p><ul><li>The session name containing the match</li><li>The request method and URL</li><li>A snippet of the matching content with the search term highlighted</li><li>The match location (URL, header, body, annotation)</li></ul><p>Click on a result to navigate to that entry in its session.</p><h2 id="autocomplete-suggestions" tabindex="-1">Autocomplete Suggestions <a class="header-anchor" href="#autocomplete-suggestions" aria-label="Permalink to &quot;Autocomplete Suggestions&quot;">​</a></h2><p>As you type in the filter bar or global search, NectoProxy provides <strong>autocomplete suggestions</strong> based on the captured traffic data.</p><h3 id="what-is-suggested" tabindex="-1">What is Suggested <a class="header-anchor" href="#what-is-suggested" aria-label="Permalink to &quot;What is Suggested&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Context</th><th>Suggestions</th></tr></thead><tbody><tr><td><strong>Host filter</strong></td><td>Hostnames seen in captured traffic</td></tr><tr><td><strong>URL filter</strong></td><td>URL paths seen in captured traffic</td></tr><tr><td><strong>Status filter</strong></td><td>Status codes seen in captured traffic</td></tr><tr><td><strong>Content Type filter</strong></td><td>Content types seen in captured traffic</td></tr><tr><td><strong>Global search</strong></td><td>Recent search queries and matching URL patterns</td></tr></tbody></table><h3 id="how-suggestions-work" tabindex="-1">How Suggestions Work <a class="header-anchor" href="#how-suggestions-work" aria-label="Permalink to &quot;How Suggestions Work&quot;">​</a></h3><ol><li>Start typing in a filter field</li><li>A dropdown appears showing matching suggestions from the captured data</li><li>Use arrow keys to navigate suggestions</li><li>Press Enter or click to select a suggestion</li><li>The filter is applied immediately</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Autocomplete suggestions are generated from your actual traffic data. This means suggestions are always relevant to what NectoProxy has captured, rather than generic suggestions.</p></div><h2 id="recent-searches" tabindex="-1">Recent Searches <a class="header-anchor" href="#recent-searches" aria-label="Permalink to &quot;Recent Searches&quot;">​</a></h2><p>NectoProxy remembers your <strong>recent search queries</strong> so you can quickly re-apply previous searches.</p><h3 id="accessing-recent-searches" tabindex="-1">Accessing Recent Searches <a class="header-anchor" href="#accessing-recent-searches" aria-label="Permalink to &quot;Accessing Recent Searches&quot;">​</a></h3><ul><li>Click on the search field to see a list of recent searches</li><li>Recent searches are displayed in reverse chronological order (most recent first)</li><li>Click on a recent search to re-apply it</li></ul><h3 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h3><p>Recent searches are stored locally and persist across NectoProxy sessions. The list is maintained at a reasonable size -- older queries are removed as new ones are added.</p><h2 id="command-palette" tabindex="-1">Command Palette <a class="header-anchor" href="#command-palette" aria-label="Permalink to &quot;Command Palette&quot;">​</a></h2><p>The command palette provides <strong>quick access</strong> to all NectoProxy features, settings, and navigation through a single keyboard shortcut.</p><h3 id="opening-the-command-palette" tabindex="-1">Opening the Command Palette <a class="header-anchor" href="#opening-the-command-palette" aria-label="Permalink to &quot;Opening the Command Palette&quot;">​</a></h3><p>Press <strong><code>Ctrl+K</code></strong> (or <strong><code>Cmd+K</code></strong> on macOS) to open the command palette.</p><h3 id="what-you-can-do" tabindex="-1">What You Can Do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What You Can Do&quot;">​</a></h3><p>The command palette accepts multiple types of input:</p><table tabindex="0"><thead><tr><th>Input</th><th>Action</th></tr></thead><tbody><tr><td>Feature names</td><td>Navigate to features (e.g., &quot;Rules,&quot; &quot;Breakpoints,&quot; &quot;Dashboard&quot;)</td></tr><tr><td>Actions</td><td>Execute actions (e.g., &quot;Clear traffic,&quot; &quot;Export HAR,&quot; &quot;New session&quot;)</td></tr><tr><td>Settings</td><td>Open settings panels (e.g., &quot;Upstream proxy,&quot; &quot;SSL passthrough&quot;)</td></tr><tr><td>URLs</td><td>Filter traffic by URL</td></tr><tr><td>Commands</td><td>Execute proxy commands (e.g., &quot;Start recording,&quot; &quot;Stop recording&quot;)</td></tr></tbody></table><h3 id="example-commands" tabindex="-1">Example Commands <a class="header-anchor" href="#example-commands" aria-label="Permalink to &quot;Example Commands&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; New Session                    Create a new session</span></span>
<span class="line"><span>&gt; Export HAR                     Export current session as HAR</span></span>
<span class="line"><span>&gt; Clear Traffic                  Clear all traffic in active session</span></span>
<span class="line"><span>&gt; Toggle Rules Panel             Show/hide the rules panel</span></span>
<span class="line"><span>&gt; Toggle Recording               Start/stop traffic capture</span></span>
<span class="line"><span>&gt; Open Settings                  Open the settings panel</span></span>
<span class="line"><span>&gt; SSL Passthrough                Open SSL passthrough configuration</span></span>
<span class="line"><span>&gt; Keyboard Shortcuts             Show keyboard shortcuts help</span></span></code></pre></div><details class="details custom-block"><summary>Command Palette Features</summary><ul><li><strong>Fuzzy matching</strong> -- Type partial words and the palette finds matching commands (e.g., &quot;exp har&quot; matches &quot;Export HAR&quot;)</li><li><strong>Keyboard navigation</strong> -- Use arrow keys to navigate results, Enter to execute</li><li><strong>Context-aware</strong> -- Some commands are only available in certain contexts</li><li><strong>Fast</strong> -- The palette opens instantly and results filter as you type</li></ul></details><h2 id="practical-workflows" tabindex="-1">Practical Workflows <a class="header-anchor" href="#practical-workflows" aria-label="Permalink to &quot;Practical Workflows&quot;">​</a></h2><h3 id="workflow-1-finding-a-specific-api-call" tabindex="-1">Workflow 1: Finding a Specific API Call <a class="header-anchor" href="#workflow-1-finding-a-specific-api-call" aria-label="Permalink to &quot;Workflow 1: Finding a Specific API Call&quot;">​</a></h3><ol><li>Type the API path in the <strong>URL filter</strong>: <code>/api/orders/12345</code></li><li>If you get too many results, add the <strong>Method filter</strong>: <code>POST</code></li><li>Click on the matching entry to inspect it</li></ol><h3 id="workflow-2-investigating-all-errors" tabindex="-1">Workflow 2: Investigating All Errors <a class="header-anchor" href="#workflow-2-investigating-all-errors" aria-label="Permalink to &quot;Workflow 2: Investigating All Errors&quot;">​</a></h3><ol><li>Set the <strong>Status filter</strong> to <code>4xx</code> or <code>5xx</code></li><li>Review each error entry in the filtered list</li><li>Add <a href="./annotations.html">Annotations</a> to mark important findings</li><li>Use <strong>Global Search</strong> to check if similar errors appear in other sessions</li></ol><h3 id="workflow-3-finding-who-makes-requests-to-a-domain" tabindex="-1">Workflow 3: Finding Who Makes Requests to a Domain <a class="header-anchor" href="#workflow-3-finding-who-makes-requests-to-a-domain" aria-label="Permalink to &quot;Workflow 3: Finding Who Makes Requests to a Domain&quot;">​</a></h3><ol><li>Set the <strong>Host filter</strong> to the domain of interest: <code>analytics.example.com</code></li><li>Review the traffic to understand the request patterns</li><li>Use timing information to assess the impact on page load</li></ol><h3 id="workflow-4-quick-navigation-with-command-palette" tabindex="-1">Workflow 4: Quick Navigation with Command Palette <a class="header-anchor" href="#workflow-4-quick-navigation-with-command-palette" aria-label="Permalink to &quot;Workflow 4: Quick Navigation with Command Palette&quot;">​</a></h3><ol><li>Press <code>Ctrl+K</code> to open the command palette</li><li>Start typing what you want to do: &quot;break&quot; for breakpoints, &quot;rule&quot; for rules, &quot;dash&quot; for dashboard</li><li>Press Enter to navigate or execute the matched command</li></ol><hr><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Search and filter state is maintained while you navigate within NectoProxy. Filters remain applied until you explicitly clear them, even if you switch between detail panels and the traffic list.</p></div>`,65)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
